30	const PROCESSING_FEE = 5;
31	
32	/**
33	 * The spec keeps intermediate amounts as exact fractions and rounds only the
34	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
35	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
36	 *
37	 * So percentages are applied as integer rationals — multiply by the numerator
38	 * first, divide by the denominator last — and money is carried in hundredths
39	 * of a G. Both operands of every product stay integral, so no drift accrues.
40	 */
41	const SUBUNITS_PER_G = 100;
42	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
43	
44	/**
45	 * A modifier as an exact rational: the surcharge or discount *itself*, not the
46	 * multiplied total. +10 % is { num: 10, den: 100 }; a discount has a negative
47	 * numerator. Modifiers are summed onto a base, never multiplied through it.
48	 */
49	interface Rate {
50	  num: number;
51	  den: number;
52	}
53	
54	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 10, den: 100 };
55	const CURSE_SURCHARGE: Rate = { num: 50, den: 100 };
56	const HIGH_ENCHANTMENT_SURCHARGE: Rate = { num: 30, den: 100 };
57	
58	const LOYALTY_DISCOUNT: Rate = { num: -20, den: 100 };
59	const FOLLOW_UP_DISCOUNT: Rate = { num: -15, den: 100 };
60	
61	/** An item is highly enchanted from this level upwards. */
62	const HIGH_ENCHANTMENT_LEVEL = 5;
63	
64	/** A customer is long-standing from this many years of business upwards. */
65	const LOYALTY_YEARS = 2;
66	
67	/** The modifier amount `rate` contributes against `subunits` — not the total. */
68	const rateAmount = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;
69	
70	/** Premiums round up — in the MHPCO's favour. */
71	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
72	
73	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
74	  sword: 100,
75	  amulet: 60,
76	  staff: 80,
77	  potion: 40,
78	  rune: 25,
79	  moonstone: 25,
80	};
81	
82	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;
83	
84	const COMPONENT_TYPES = ["rune", "moonstone"];
85	
86	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
87	
88	/** Exactly this many alike components form a block, priced as one unit. */
89	const COMPONENT_BLOCK_SIZE = 3;
90	const COMPONENT_BLOCK_PREMIUM = 60;
91	
92	/** Splits items into those matching the predicate and those that do not. */
93	const partition = (items: Item[], matches: (item: Item) => boolean): [Item[], Item[]] => [
94	  items.filter(matches),
95	  items.filter((item) => !matches(item)),
96	];
97	
98	const groupByType = (items: Item[]): Map<string, Item[]> => {
99	  const groups = new Map<string, Item[]>();
100	  for (const item of items) groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
101	
102	  return groups;
103	};
104	
105	const sumOfBasePremiums = (items: Item[]): number =>
106	  items.reduce((total, item) => total + basePremiumOf(item), 0);
107	
108	/**
109	 * Alike components — those of the very same type — form a block when there are
110	 * exactly COMPONENT_BLOCK_SIZE of them; the block is priced as one unit.
111	 * Any other count is priced per component.
112	 */
113	const componentGroupPremium = (group: Item[]): number =>
114	  group.length === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(group);
115	
116	/**
117	 * The policy base premium: every insured item's base premium, summed — except
118	 * that each group of alike components is priced as blocks where it can be.
119	 */
120	const policyBasePremiumOf = (items: Item[]): number => {
121	  const [components, mainItems] = partition(items, isComponent);
122	  const componentsTotal = [...groupByType(components).values()].reduce(
123	    (total, group) => total + componentGroupPremium(group),
124	    0,
125	  );
126	
127	  return sumOfBasePremiums(mainItems) + componentsTotal;
128	};
129	
130	/** The total the given rates contribute against a shared base. */
131	const sumOfRateAmounts = (base: number, rates: Rate[]): number =>
132	  rates.reduce((total, rate) => total + rateAmount(base, rate), 0);
133	
134	const isHighlyEnchanted = (item: Item): boolean =>
135	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
136	
137	/** Which item-specific modifiers an item attracts, by its own attributes. */
138	const ratesForItem = (item: Item): Rate[] => [
139	  ...(item.cursed ? [CURSE_SURCHARGE] : []),
140	  ...(isHighlyEnchanted(item) ? [HIGH_ENCHANTMENT_SURCHARGE] : []),
141	];
142	
143	const isLongStanding = (customer: Customer): boolean =>
144	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
145	
146	/** Which policy-wide modifiers a policy attracts, by the customer's history. */
147	const ratesForPolicy = (customer: Customer, precedingQuotes: number): Rate[] => [
148	  FIRST_INSURANCE_SURCHARGE,
149	  ...(isLongStanding(customer) ? [LOYALTY_DISCOUNT] : []),
150	  ...(precedingQuotes > 0 ? [FOLLOW_UP_DISCOUNT] : []),
151	];
152	
153	/** Item-specific modifiers apply to the affected item's own base premium. */
154	const sumOfItemModifierAmounts = (items: Item[]): number =>
155	  items.reduce(
156	    (total, item) =>
157	      total + sumOfRateAmounts(toSubunits(basePremiumOf(item)), ratesForItem(item)),
158	    0,
159	  );
160	
161	/**
162	 * Modifiers are additive amounts, each computed against its own base: item
163	 * modifiers against the affected item, policy-wide modifiers against the
164	 * policy base premium. The processing fee is added at the very end.
165	 */
166	const quotePremium = (items: Item[], customer: Customer, precedingQuotes: number): number => {
167	  const policyBase = toSubunits(policyBasePremiumOf(items));
168	
169	  return toPremiumGold(
170	    policyBase +
171	      sumOfItemModifierAmounts(items) +
172	      sumOfRateAmounts(policyBase, ratesForPolicy(customer, precedingQuotes)) +
173	      toSubunits(PROCESSING_FEE),
174	  );
175	};
176	
177	/**
178	 * Steps are processed in order, since a step's result can depend on those
179	 * before it — a quote is discounted once the customer holds an earlier one.
180	 */
181	export const runScenario = (scenario: Scenario): ScenarioResults => {
182	  const results: QuoteResult[] = [];
183	  let quotesSoFar = 0;
184	
185	  for (const step of scenario.steps) {
186	    results.push({ premium: quotePremium(step.items, scenario.customer, quotesSoFar) });
187	    quotesSoFar += 1;
188	  }
189	
190	  return { results };
191	};
