export const runScenario = (scenario: Scenario): ScenarioResults => {
  const results: QuoteResult[] = [];
  const standing: CustomerStanding = { customer: scenario.customer, quotesSoFar: 0 };

  for (const step of scenario.steps) {
    results.push({ premium: quotePremium(step.items, standing) });
